import{b as t,O as a,g as e,j as i}from"./chunks/framework.DcaUmd3X.js";const k=JSON.parse('{"title":"测试发现与命名","description":"","frontmatter":{},"headers":[],"relativePath":"automation/pytest/intro/test-discovery/index.md","filePath":"自动化测试/2.pytest+requests/1.入门篇/04.测试发现与命名.md","lastUpdated":1786983642000}'),n={name:"automation/pytest/intro/test-discovery/index.md"};function p(d,s,l,o,h,c){return a(),e("div",null,[...s[0]||(s[0]=[i(`<h1 id="测试发现与命名" tabindex="-1">测试发现与命名 <a class="header-anchor" href="#测试发现与命名" aria-label="Permalink to &quot;测试发现与命名&quot;">​</a></h1><blockquote><p>pytest 不要求你注册任何测试——它靠一套命名规则「自动发现」测试。理解这套规则，你就知道为什么有的函数会被跑、有的不会，也知道 <code>test_cart.py::test_empty_cart</code> 这种「节点 ID」是怎么来的。</p></blockquote><h2 id="为什么要理解发现规则" tabindex="-1">为什么要理解发现规则 <a class="header-anchor" href="#为什么要理解发现规则" aria-label="Permalink to &quot;为什么要理解发现规则&quot;">​</a></h2><p>pytest 运行前会先做一件事：<strong>从根目录递归扫描，按命名规范找出所有测试</strong>。这个「发现（discovery）」过程决定了哪些代码会被当成测试执行。</p><p>理解它有实际价值：</p><ul><li>写了个测试却没被执行，几乎都是命名没对上规则</li><li>团队协作时，命名规范统一了，<code>pytest -k</code> 筛选、报告定位才精准</li><li>想控制「只跑某个目录」或「跳过某个文件」，都得先懂发现机制</li></ul><h2 id="三条命名规则" tabindex="-1">三条命名规则 <a class="header-anchor" href="#三条命名规则" aria-label="Permalink to &quot;三条命名规则&quot;">​</a></h2><p>pytest 默认按三条规则识别测试：</p><table tabindex="0"><thead><tr><th>层级</th><th>默认规则</th><th>例子 ✅</th><th>反例 ❌</th></tr></thead><tbody><tr><td>文件</td><td><code>test_*.py</code> 或 <code>*_test.py</code></td><td><code>test_cart.py</code>、<code>cart_test.py</code></td><td><code>cart.py</code>、<code>test.py</code></td></tr><tr><td>函数</td><td><code>test_</code> 开头</td><td><code>test_add()</code></td><td><code>add_test()</code>、<code>check_add()</code></td></tr><tr><td>类</td><td><code>Test</code> 开头，且无 <code>__init__</code></td><td><code>class TestCart:</code></td><td><code>class CartTest:</code>、带 <code>__init__</code> 的 <code>Test</code> 类</td></tr></tbody></table><p>三条规则一起作用。一个 <code>test_cart.py</code> 文件里的 <code>test_add</code> 函数会被收集；而同一个文件里的普通辅助函数 <code>_helper()</code> 不会。</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># test_cart.py</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> test_total</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">():           </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ✅ 收集：test_ 开头</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    ...</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> helper</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">():               </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ❌ 跳过：没有 test_ 前缀</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    ...</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> TestCart</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:             </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ✅ 收集：Test 开头、无 __init__</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> test_add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(self):     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ✅ 收集：test_ 开头的方法</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        ...</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> TestCartWithInit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ❌ 跳过：有 __init__ 方法</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    def</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> __init__</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(self):</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        ...</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> test_add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(self):</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        ...</span></span></code></pre></div><h2 id="递归扫描与-testpaths" tabindex="-1">递归扫描与 <code>testpaths</code> <a class="header-anchor" href="#递归扫描与-testpaths" aria-label="Permalink to &quot;递归扫描与 \`testpaths\`&quot;">​</a></h2><p>pytest 从 <code>rootdir</code>（项目根目录）出发，<strong>递归地</strong>进入每个子目录找测试文件。所以测试可以组织成任意深的目录树：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tests/</span></span>
<span class="line"><span>├── test_products.py</span></span>
<span class="line"><span>├── cart/</span></span>
<span class="line"><span>│   └── test_cart.py</span></span>
<span class="line"><span>└── orders/</span></span>
<span class="line"><span>    └── test_orders.py</span></span></code></pre></div><p>默认它会扫<strong>所有</strong>符合 <code>python_files</code> 规则的文件。如果你的项目目录很大（比如还混着前端 <code>node_modules</code>、后端代码），扫描会很慢甚至误扫。这时用配置限定只扫测试目录：</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># pytest.ini 或 pyproject.toml（配置详见进阶篇·配置）</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">testpaths</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = tests</span></span></code></pre></div><blockquote><p><strong>要点：<code>testpaths</code> 告诉 pytest「只在这几个目录里找测试」。它同时是性能优化（不扫无关目录）和防止误收集的手段。默认不设时，pytest 会从 rootdir 递归扫描全部。</strong></p></blockquote><h2 id="节点-id-每个测试的-身份证" tabindex="-1">节点 ID：每个测试的&quot;身份证&quot; <a class="header-anchor" href="#节点-id-每个测试的-身份证" aria-label="Permalink to &quot;节点 ID：每个测试的&quot;身份证&quot;&quot;">​</a></h2><p>每个被收集到的测试都有一个唯一的<strong>节点 ID（node ID）</strong>，格式是「文件::类::函数」，用 <code>::</code> 分隔：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>test_cart.py::test_total                    # 模块里的函数</span></span>
<span class="line"><span>test_cart.py::TestCart::test_add            # 类里的方法</span></span>
<span class="line"><span>tests/cart/test_cart.py::test_remove        # 带子目录路径</span></span></code></pre></div><p>节点 ID 是你<strong>精确定位单个测试</strong>的工具：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pytest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test_cart.py::test_total</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # 只跑这一个函数</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pytest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test_cart.py::TestCart</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                 # 跑整个类</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pytest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test_cart.py::TestCart::test_add</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # 跑类里的一个方法</span></span></code></pre></div><p>跑测试时 <code>-v</code> 显示的就是节点 ID。报告、日志、<code>--lf</code> 重跑清单里也都是它——它是测试的稳定标识。</p><h2 id="类的细节-为什么-test-类不能有-init" tabindex="-1">类的细节：为什么 <code>Test</code> 类不能有 <code>__init__</code> <a class="header-anchor" href="#类的细节-为什么-test-类不能有-init" aria-label="Permalink to &quot;类的细节：为什么 \`Test\` 类不能有 \`__init__\`&quot;">​</a></h2><p>pytest 收集类有个冷门但重要的规则：<strong><code>Test</code> 开头的类如果定义了 <code>__init__</code>，会被直接跳过</strong>。</p><p>原因是 pytest 收集到测试类时，会<strong>为每个测试方法创建一个新的类实例</strong>。如果类有 <code>__init__</code> 需要传参，pytest 无法知道该传什么，于是干脆跳过。</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> TestCart</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # ❌ 不要写 __init__。想初始化数据，用 fixture（核心篇讲）</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> test_add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(self):</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        ...</span></span></code></pre></div><p>想「每个测试方法共享初始状态」，正确姿势是 fixture（核心篇），而不是在 <code>__init__</code> 里塞东西——这也是为什么 pytest 社区普遍建议「测试类只是个组织容器，不该有状态」。</p><h2 id="init-py-与包结构" tabindex="-1"><code>__init__.py</code> 与包结构 <a class="header-anchor" href="#init-py-与包结构" aria-label="Permalink to &quot;\`__init__.py\` 与包结构&quot;">​</a></h2><p>测试目录里要不要放 <code>__init__.py</code>？这关系到 import 模式（上一章提过）：</p><ul><li><strong>不建 <code>__init__.py</code></strong>：目录是「普通目录」，pytest 用默认的 prepend 模式，把目录插进 <code>sys.path</code> 直接 import。<strong>这是最常见的做法，开箱即用。</strong></li><li><strong>建 <code>__init__.py</code></strong>：目录变成「包」，配合 importlib 模式，import 走标准语义。适合复杂的多级包结构。</li></ul><p>对新手来说，<strong>测试目录里不建 <code>__init__.py</code>、用默认配置</strong>就够了。等你的项目结构复杂到出现「两个模块同名」的冲突时，再考虑包结构和 importlib 模式（进阶篇·配置有完整说明）。</p><blockquote><p><strong>要点：大多数教程里测试目录都没有 <code>__init__.py</code>，这不是遗漏，而是刻意为之——避免包结构带来的 import 复杂度。</strong></p></blockquote><h2 id="排查-为什么我的测试没被收集到" tabindex="-1">排查：为什么我的测试没被收集到 <a class="header-anchor" href="#排查-为什么我的测试没被收集到" aria-label="Permalink to &quot;排查：为什么我的测试没被收集到&quot;">​</a></h2><p>这是新手最高频的问题。按下面清单自查：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pytest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --collect-only</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 先看 pytest 到底收集到了哪些测试</span></span></code></pre></div><table tabindex="0"><thead><tr><th>症状</th><th>可能原因</th><th>检查</th></tr></thead><tbody><tr><td><code>collected 0 items</code></td><td>文件名没对上规则</td><td>文件名是 <code>test_</code> 开头或 <code>_test</code> 结尾吗？</td></tr><tr><td>函数没被跑</td><td>函数名没 <code>test_</code> 前缀</td><td>是 <code>test_xxx</code> 还是 <code>xxx_test</code>？</td></tr><tr><td>类没被跑</td><td>类名不是 <code>Test</code> 开头 / 有 <code>__init__</code></td><td>检查类名和 <code>__init__</code></td></tr><tr><td>目录里的测试没找到</td><td><code>testpaths</code> 配错了 / 目录不在扫描范围</td><td>检查配置和目录层级</td></tr><tr><td>文件在但报 import 错误</td><td>模块名冲突 / 依赖没装</td><td>看收集阶段的报错信息</td></tr></tbody></table><p><code>--collect-only</code> 是排查发现问题的第一工具——它能列出所有被识别的测试，一眼看出「是不是根本没收集到」还是「收集到了但执行时报错」。这两者性质完全不同。</p><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ul><li>pytest 按三条规则发现测试：<strong>文件名</strong>（<code>test_*.py</code>/<code>*_test.py</code>）、<strong>函数名</strong>（<code>test_</code> 开头）、<strong>类名</strong>（<code>Test</code> 开头且无 <code>__init__</code>）</li><li>pytest 从 <code>rootdir</code> 递归扫描，<code>testpaths</code> 可限定只扫测试目录</li><li>每个测试有唯一<strong>节点 ID</strong>（<code>文件::类::函数</code>），用来精确指定单个测试</li><li><code>Test</code> 类不能有 <code>__init__</code>，因为 pytest 会为每个测试方法新建实例；初始化用 fixture 而不是构造函数</li><li>测试目录通常<strong>不建 <code>__init__.py</code></strong>，避免包结构的 import 复杂度</li><li><code>pytest --collect-only</code> 是排查「测试没被收集到」的第一工具</li></ul>`,40)])])}const _=t(n,[["render",p]]);export{k as __pageData,_ as default};
